B.Pa=new A.dy("isci_mazeret","\u0130\u015f\xe7i do\u011fum, s\xfct ve mazeret izinleri","\u0130\u015f\xe7i do\u011fum izni","\u0130\u015f\xe7i do\u011fum izni ka\xe7 hafta?",B.aaB,"Kad\u0131n i\u015f\xe7iler do\u011fumdan \xf6nce 8, do\u011fumdan sonra 16 hafta olmak \xfczere toplam 24 hafta \xe7al\u0131\u015ft\u0131r\u0131lmaz (\xe7o\u011ful gebelikte do\u011fum \xf6ncesi s\xfcreye 2 hafta eklenir). Bir ya\u015f\u0131ndan k\xfc\xe7\xfck \xe7ocu\u011funu emzirmesi i\xe7in kad\u0131n i\u015f\xe7iye g\xfcnde toplam 1,5 saat s\xfct izni verilir. \u0130\u015f\xe7iye evlenmesi veya evlat edinmesi ya da ana, baba, e\u015f, karde\u015f veya \xe7ocu\u011funun \xf6l\xfcm\xfc h\xe2linde 3 g\xfcn, e\u015finin do\u011fum yapmas\u0131 h\xe2linde 10 g\xfcn \xfccretli izin verilir.",B.aaW,"Do\u011fum sonras\u0131 \xfccretsiz izinler (\xf6r. 6 aya kadar, ilk do\u011fumda 60 g\xfcn yar\u0131m \xe7al\u0131\u015fma) ve koruyucu aile izni de kanunda d\xfczenlidir; ayr\u0131nt\u0131 i\xe7in md. 74'\xfcn tamam\u0131na bak.",u.a,B.ee)
B.ac0=s(["isci","calisma suresi","haftalik calisma","calisma saati","45 saat","fazla mesai","fazla calisma","mesai","is kanunu","4857"],t.s)
B.agU=new A.bs("4857 say\u0131l\u0131 \u0130\u015f Kanunu, md. 63 (\xc7al\u0131\u015fma s\xfcresi)","Genel bak\u0131mdan \xe7al\u0131\u015fma s\xfcresi haftada en \xe7ok k\u0131rkbe\u015f saattir. Aksi kararla\u015ft\u0131r\u0131lmam\u0131\u015fsa bu s\xfcre, i\u015fyerlerinde haftan\u0131n \xe7al\u0131\u015f\u0131lan g\xfcnlerine e\u015fit \xf6l\xe7\xfcde b\xf6l\xfcnerek uygulan\u0131r.")
B.ah5=new A.bs("4857 say\u0131l\u0131 \u0130\u015f Kanunu, md. 41 (Fazla \xe7al\u0131\u015fma)","Fazla \xe7al\u0131\u015fma, Kanunda yaz\u0131l\u0131 ko\u015fullar \xe7er\xe7evesinde, haftal\u0131k k\u0131rkbe\u015f saati a\u015fan \xe7al\u0131\u015fmalard\u0131r.")
B.ahq=new A.bs("4857 say\u0131l\u0131 \u0130\u015f Kanunu, md. 41 (Fazla \xe7al\u0131\u015fma \xfccreti)","Her bir saat fazla \xe7al\u0131\u015fma i\xe7in verilecek \xfccret normal \xe7al\u0131\u015fma \xfccretinin saat ba\u015f\u0131na d\xfc\u015fen miktar\u0131n\u0131n y\xfczde elli y\xfckseltilmesi suretiyle \xf6denir.")
B.agJ=new A.bs("4857 say\u0131l\u0131 \u0130\u015f Kanunu, md. 41 (Serbest zaman)","Fazla \xe7al\u0131\u015fma veya fazla s\xfcrelerle \xe7al\u0131\u015fma yapan i\u015f\xe7i isterse, bu \xe7al\u0131\u015fmalar kar\u015f\u0131l\u0131\u011f\u0131 zaml\u0131 \xfccret yerine, fazla \xe7al\u0131\u015ft\u0131\u011f\u0131 her saat kar\u015f\u0131l\u0131\u011f\u0131nda bir saat otuz dakikay\u0131, fazla s\xfcrelerle \xe7al\u0131\u015ft\u0131\u011f\u0131 her saat kar\u015f\u0131l\u0131\u011f\u0131nda bir saat onbe\u015f dakikay\u0131 serbest zaman olarak kullanabilir. \u0130\u015f\xe7i hak etti\u011fi serbest zaman\u0131 alt\u0131 ay zarf\u0131nda, \xe7al\u0131\u015fma s\xfcreleri i\xe7inde ve \xfccretinde bir kesinti olmadan kullan\u0131r.")
B.ahD=new A.bs("4857 say\u0131l\u0131 \u0130\u015f Kanunu, md. 41 (Onay ve s\u0131n\u0131r)","Fazla saatlerle \xe7al\u0131\u015fmak i\xe7in i\u015f\xe7inin onay\u0131n\u0131n al\u0131nmas\u0131 gerekir. Fazla \xe7al\u0131\u015fma s\xfcresinin toplam\u0131 bir y\u0131lda ikiy\xfczyetmi\u015f saatten fazla olamaz.")
B.a6i=s([B.agU,B.ah5,B.ahq,B.agJ,B.ahD],t.Q)
B.Ph=new A.dy("isci_calisma","\u0130\u015f\xe7i \xe7al\u0131\u015fma s\xfcresi ve fazla \xe7al\u0131\u015fma","\u0130\u015f\xe7i \xe7al\u0131\u015fma saati","\u0130\u015f\xe7i haftal\u0131k \xe7al\u0131\u015fma s\xfcresi ve fazla mesai \xfccreti nedir?",B.ac0,"\u0130\u015f Kanunu'na g\xf6re genel olarak \xe7al\u0131\u015fma s\xfcresi haftada en \xe7ok 45 saattir; aksi kararla\u015ft\u0131r\u0131lmam\u0131\u015fsa \xe7al\u0131\u015f\u0131lan g\xfcnlere e\u015fit b\xf6l\xfcn\xfcr. Haftal\u0131k 45 saati a\u015fan \xe7al\u0131\u015fma fazla \xe7al\u0131\u015fmad\u0131r: her saat i\xe7in normal saat \xfccreti %50 art\u0131r\u0131larak \xf6denir. Fazla \xe7al\u0131\u015fma i\xe7in i\u015f\xe7inin onay\u0131 gerekir ve bir y\u0131lda toplam 270 saati a\u015famaz. \u0130\u015f\xe7i isterse zaml\u0131 \xfccret yerine fazla \xe7al\u0131\u015ft\u0131\u011f\u0131 her saat i\xe7in 1 saat 30 dakika serbest zaman kullanabilir (alt\u0131 ay i\xe7inde).",B.a6i,"Yer alt\u0131 maden i\u015fleri gibi \xf6zel i\u015flerde s\xfcreler farkl\u0131d\u0131r; kamu i\u015fyerinde toplu i\u015f s\xf6zle\u015fmesi h\xfck\xfcmleri de ge\xe7erli olabilir.",u.a,B.ee)
B.acw=s(["isci","ihbar","ihbar suresi","bildirim suresi","fesih","isten cikar","isten cikma","isten atma","is sozlesmesi","gecerli neden","is guvencesi","is kanunu","4857"],t.s)
B.ah9=new A.bs("4857 say\u0131l\u0131 \u0130\u015f Kanunu, md. 17 (Bildirim s\xfcreleri)","\u0130\u015f s\xf6zle\u015fmeleri; a) \u0130\u015fi alt\u0131 aydan az s\xfcrm\xfc\u015f olan i\u015f\xe7i i\xe7in, bildirimin di\u011fer tarafa yap\u0131lmas\u0131ndan ba\u015flayarak iki hafta sonra, b) \u0130\u015fi alt\u0131 aydan birbu\xe7uk y\u0131la kadar s\xfcrm\xfc\u015f olan i\u015f\xe7i i\xe7in, bildirimin di\u011fer tarafa yap\u0131lmas\u0131ndan ba\u015flayarak d\xf6rt hafta sonra, c) \u0130\u015fi birbu\xe7uk y\u0131ldan \xfc\xe7 y\u0131la kadar s\xfcrm\xfc\u015f olan i\u015f\xe7i i\xe7in, bildirimin di\u011fer tarafa yap\u0131lmas\u0131ndan ba\u015flayarak alt\u0131 hafta sonra, d) \u0130\u015fi \xfc\xe7 y\u0131ldan fazla s\xfcrm\xfc\u015f i\u015f\xe7i i\xe7in, bildirim yap\u0131lmas\u0131ndan ba\u015flayarak sekiz hafta sonra, feshedilmi\u015f say\u0131l\u0131r. Bu s\xfcreler asgari olup s\xf6zle\u015fmeler ile art\u0131r\u0131labilir. Bildirim \u015fart\u0131na uymayan taraf, bildirim s\xfcresine ili\u015fkin \xfccret tutar\u0131nda tazminat \xf6demek zorundad\u0131r.")
B.agK=new A.bs("4857 say\u0131l\u0131 \u0130\u015f Kanunu, md. 18 (Feshin ge\xe7erli sebebe dayand\u0131r\u0131lmas\u0131)","Otuz veya daha fazla i\u015f\xe7i \xe7al\u0131\u015ft\u0131ran i\u015fyerlerinde en az alt\u0131 ayl\u0131k k\u0131demi olan i\u015f\xe7inin belirsiz s\xfcreli i\u015f s\xf6zle\u015fmesini fesheden i\u015fveren, i\u015f\xe7inin yeterlili\u011finden veya davran\u0131\u015flar\u0131ndan ya da i\u015fletmenin, i\u015fyerinin veya i\u015fin gereklerinden kaynaklanan ge\xe7erli bir sebebe dayanmak zorundad\u0131r.")
B.aah=s([B.ah9,B.agK],t.Q)
B.Pc=new A.dy("isci_fesih","\u0130\u015f s\xf6zle\u015fmesinin feshi ve ihbar s\xfcreleri","\u0130\u015f\xe7i ihbar s\xfcresi","\u0130hbar s\xfcresi ne kadar?",B.acw,"Belirsiz s\xfcreli i\u015f s\xf6zle\u015fmesini feshetmeden \xf6nce kar\u015f\u0131 tarafa bildirim yap\u0131lmas\u0131 gerekir. Bildirim s\xfcreleri en az: i\u015fi 6 aydan az s\xfcrm\xfc\u015f i\u015f\xe7i i\xe7in 2 hafta, 6 ay\u20131,5 y\u0131l i\xe7in 4 hafta, 1,5\u20133 y\u0131l i\xe7in 6 hafta, 3 y\u0131ldan fazla i\xe7in 8 hafta. Bildirim \u015fart\u0131na uymayan taraf, bildirim s\xfcresine ait \xfccret tutar\u0131nda tazminat \xf6der. En az 30 i\u015f\xe7i \xe7al\u0131\u015ft\u0131ran i\u015fyerinde en az 6 ayl\u0131k k\u0131demi olan i\u015f\xe7iyi \xe7\u0131karan i\u015fveren ge\xe7erli bir sebebe dayanmak zorundad\u0131r.",B.aah,"\u0130\u015ften \xe7\u0131kar\u0131ld\u0131\u011f\u0131nda dava ve ba\u015fvuru s\xfcreleri k\u0131sad\u0131r; ki\u015fisel durumun i\xe7in bir avukata veya i\u015f m\xfcfetti\u015fli\u011fine dan\u0131\u015f.",u.a,B.ee)
B.a4R=s(["kidem","kidem tazminati","tazminat","isci","is kanunu","1475"],t.s)
B.ahr=new A.bs("1475 say\u0131l\u0131 \u0130\u015f Kanunu, md. 14 (K\u0131dem tazminat\u0131 hakk\u0131)","hizmet aktinin devam\u0131 s\xfcresince her ge\xe7en tam y\u0131l i\xe7in i\u015fverence i\u015f\xe7iye 30 g\xfcnl\xfck \xfccreti tutar\u0131nda k\u0131dem tazminat\u0131 \xf6denir. Bir y\u0131ldan artan s\xfcreler i\xe7in de ayn\u0131 oran \xfczerinden \xf6deme yap\u0131l\u0131r.")
B.aho=new A.bs("1475 say\u0131l\u0131 \u0130\u015f Kanunu, md. 14 (Hak do\u011furan haller)","1. \u0130\u015fveren taraf\u0131ndan bu Kanunun 17 nci maddesinin II numaral\u0131 bendinde g\xf6sterilen sebepler d\u0131\u015f\u0131nda, 2. \u0130\u015f\xe7i taraf\u0131ndan bu Kanunun 16 nc\u0131 maddesi uyar\u0131nca, 3. Muvazzaf askerlik hizmeti dolay\u0131s\u0131yle,")
B.ahf=new A.bs("1475 say\u0131l\u0131 \u0130\u015f Kanunu, md. 14 (Hesap)","K\u0131dem tazminat\u0131n\u0131n hesaplanmas\u0131, son \xfccret \xfczerinden yap\u0131l\u0131r.")
B.agX=new A.bs("1475 say\u0131l\u0131 \u0130\u015f Kanunu, md. 14 (\xdccrete eklenen menfaatler)","k\u0131dem tazminat\u0131na esas olacak \xfccretin hesab\u0131nda 26 nc\u0131 maddenin birinci f\u0131kras\u0131nda yaz\u0131l\u0131 \xfccrete ilaveten i\u015f\xe7iye sa\u011flanm\u0131\u015f olan para ve para ile \xf6l\xe7\xfclmesi m\xfcmk\xfcn akdi ve kanundan do\u011fan menfaatler de g\xf6z\xf6n\xfcnde tutulur.")
B.agN=new A.bs("1475 say\u0131l\u0131 \u0130\u015f Kanunu, md. 14 (Tek \xf6deme)","Ayn\u0131 k\u0131dem s\xfcresi i\xe7in bir defadan fazla k\u0131dem tazminat\u0131 veya ikramiye \xf6denmez.")
